import React, { useState } from 'react';
import { lab3Api } from '../services/api';
import FunctionSelector from '../components/lab3/FunctionSelector';
import MethodSelector from '../components/lab3/MethodSelector';
import IntegrationChart from '../components/lab3/IntegrationChart';
import {IntegrationRequest, IntegrationResponse} from "../types";

const IntegrationPage = () => {
    const [request, setRequest] = useState<IntegrationRequest>({
        functionId: 1,
        methodId: 5, // По умолчанию Симпсон
        a: 0,
        b: 2,
        epsilon: 0.01
    });

    const [response, setResponse] = useState<IntegrationResponse | null>(null);
    const [loading, setLoading] = useState(false);

    const handleCalculate = async () => {
        setLoading(true);
        try {
            const res = await lab3Api.calculate(request);
            setResponse(res.data);
        } catch (err: any) {
            alert(err.response?.data?.message || "Ошибка при расчете");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-6 max-w-6xl mx-auto space-y-6">
            <h1 className="text-3xl font-bold text-gray-800">Численное интегрирование</h1>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-6 bg-white p-6 rounded-xl shadow-sm border">
                    <FunctionSelector
                        selected={request.functionId}
                        onChange={(id) => setRequest({...request, functionId: id})}
                    />

                    <MethodSelector
                        selected={request.methodId}
                        onChange={(id) => setRequest({...request, methodId: id})}
                    />

                    <div className="grid grid-cols-3 gap-4">
                        <div>
                            <label className="block text-sm font-medium">Нижний предел (a)</label>
                            <input
                                type="number"
                                value={request.a}
                                onChange={e => setRequest({...request, a: +e.target.value})}
                                className="w-full p-2 border rounded"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium">Верхний предел (b)</label>
                            <input
                                type="number"
                                value={request.b}
                                onChange={e => setRequest({...request, b: +e.target.value})}
                                className="w-full p-2 border rounded"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium">Точность (ε)</label>
                            <input
                                type="number"
                                step="0.001"
                                value={request.epsilon}
                                onChange={e => setRequest({...request, epsilon: +e.target.value})}
                                className="w-full p-2 border rounded"
                            />
                        </div>
                    </div>

                    <button
                        onClick={handleCalculate}
                        disabled={loading}
                        className="w-full py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-400"
                    >
                        {loading ? 'Считаем...' : 'Вычислить интеграл'}
                    </button>
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border min-h-[400px]">
                    {response && response.status === 'success' ? (
                        <div className="space-y-4">
                            <div className="grid grid-cols-3 gap-2 text-center">
                                <div className="p-2 bg-blue-50 rounded">
                                    <p className="text-xs text-gray-500">Результат</p>
                                    <p className="font-bold text-blue-700">{response.result?.toFixed(6)}</p>
                                </div>
                                <div className="p-2 bg-green-50 rounded">
                                    <p className="text-xs text-gray-500">Разбиений (n)</p>
                                    <p className="font-bold text-green-700">{response.n}</p>
                                </div>
                                <div className="p-2 bg-purple-50 rounded">
                                    <p className="text-xs text-gray-500">Погрешность</p>
                                    <p className="font-bold text-purple-700">{response.error?.toExponential(2)}</p>
                                </div>
                            </div>
                            <IntegrationChart points={response.graphPoints} a={request.a} b={request.b} />
                        </div>
                    ) : (
                        <div className="flex items-center justify-center h-full text-gray-400">
                            Введите данные и нажмите "Вычислить"
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default IntegrationPage;
